 * // => { filename: 'path/to/parser.js', functionName: 'parse' }
 * parseFileTransformReference('file://C:\\path\\parser.js')
 * // => { filename: 'C:\\path\\parser.js' }
 * parseFileTransformReference('file://C:\\path\\parser.js:parse')
 * // => { filename: 'C:\\path\\parser.js', functionName: 'parse' }
